with metrics as (select *, avg(shipping_fee) over (order by shipping_fee, id rows between 6 preceding and current row) as shipping_fee_avg_6, last_value(shipping_fee) ignore nulls over (partition by status order by shipping_fee, id rows between unbounded preceding and current row) as last_known_shipping_fee, percent_rank() over (partition by channel, status order by amount desc) as amount_percent_rank, ntile(5) over (partition by customer_id order by shipping_fee desc, id) as shipping_fee_bucket, ntile(5) over (partition by store_id order by shipping_fee, id) as shipping_fee_bucket_2 from orders) select s.id, s.customer_id, s.store_id, s.order_date, s.channel, s.amount, s.discount, s.shipping_fee, s.shipping_fee_avg_6, (select sum(x.monthly_fee) from subscriptions x where x.customer_id = s.customer_id) as sum_subscription_monthly_fee from metrics s order by shipping_fee desc nulls last;
